// Tryum -> n8n: check the call is genuine, then turn the event into the
// message a shop owner actually reads on their phone.
//
// The signature covers the exact bytes Tryum sent. That is why this reads the
// raw body instead of the parsed JSON: re-serializing would reformat the
// numbers (200000.00 becomes 200000) and nothing would ever verify again.
const crypto = require('crypto');

const secret = $env.TRYUM_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('TRYUM_WEBHOOK_SECRET is not set on this n8n instance');
}

// How far out of step the two clocks may be. Long enough for a container that
// has just woken up, short enough that a captured request is useless tomorrow.
const TOLERANCE_SECONDS = 300;

function money(value) {
  return Number(value || 0).toLocaleString('vi-VN') + 'd';
}

function format(evt) {
  const d = evt.data || {};
  switch (evt.event) {
    case 'sale.completed':
      return [
        '<b>Hoa don ' + d.code + '</b>',
        'Khach: ' + (d.customerName || 'Khach le'),
        'Tong: <b>' + money(d.totalAmount) + '</b> (' + d.itemCount + ' mat hang)',
        'Thu ngan: ' + (d.cashier || '-'),
      ].join('\n');

    case 'order.created':
      return [
        '<b>Don moi ' + d.orderNumber + '</b>',
        'Khach: ' + (d.customerName || '-') + (d.customerPhone ? ' - ' + d.customerPhone : ''),
        'Tong: <b>' + money(d.total) + '</b> (' + d.itemCount + ' mat hang)',
        '<i>Chua thanh toan</i>',
      ].join('\n');

    case 'inventory.low_stock':
      return [
        '<b>Sap het hang</b>',
        d.name + (d.sku ? ' (' + d.sku + ')' : ''),
        'Con ' + d.stockQuantity + ', dinh muc ' + d.minStockThreshold,
        'Vua ban o ' + d.triggeredBy,
      ].join('\n');

    default:
      // An event this workflow has no opinion about. Dropping it silently is
      // how Tryum can add an event key without breaking the shops already
      // running this workflow.
      return null;
  }
}

const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};

  let raw;
  if (item.binary && item.binary.data) {
    raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  } else {
    raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body);
  }

  const timestamp = String(headers['x-tryum-timestamp'] || '');
  const signature = String(headers['x-tryum-signature'] || '');
  const expected = 'sha256=' + crypto
    .createHmac('sha256', secret)
    .update(timestamp + '.' + raw)
    .digest('hex');

  // Length is checked first because timingSafeEqual throws on a mismatch.
  if (signature.length !== expected.length ||
      !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) {
    throw new Error('Bad signature, refusing delivery ' + headers['x-tryum-delivery']);
  }

  const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
  if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) {
    throw new Error('Stale delivery ' + headers['x-tryum-delivery'] + ', ' + age + 's old');
  }

  const evt = JSON.parse(raw);
  const message = format(evt);
  if (message) {
    out.push({
      json: {
        event: evt.event,
        storeId: evt.storeId,
        deliveryId: evt.eventId,
        chatId: $env.TRYUM_TELEGRAM_CHAT_ID,
        message,
      },
    });
  }
}

return out;
